mapper.sql:
WHERE s.deleted=0 AND c.owner_id IS NOT NULL


    AND (s.order_no LIKE CONCAT('%',#{query.keyword},'%') OR c.company_name LIKE CONCAT('%',#{query.keyword},'%') OR q.quote_no LIKE CONCAT('%',#{query.keyword},'%') OR o.real_name LIKE CONCAT('%',#{query.keyword},'%'))
    AND s.status=#{query.status}
    AND s.created_at >= #{query.dateFrom}
    AND s.created_at < DATE_ADD(#{query.dateTo},INTERVAL 1 DAY)
